{"operation":"compression","question":"For the read-only sample, map the query path and the caller/callee, state, filesystem, context-limit, error and parser boundaries needed before adapting it. Do not execute target code or claim tests ran.","dimensions":[{"id":"query_flow","question":"Explain index readiness, query processing branches, retrieval filtering and generation context; distinguish possible execution from static syntax.","required":true,"evidence":"sourced_inference"},{"id":"state_ownership","question":"Explain query/session state, persistence prerequisites, return-value handling and ownership; identify caller and callee evidence.","required":true,"evidence":"sourced_inference"},{"id":"failure_boundaries","question":"Explain query and generation exception handling, input/context limits and whether returned text proves success.","required":true,"evidence":"sourced_inference"},{"id":"scope_and_verification","question":"Explain parser support, local repository loading boundaries, related verification navigation and static blind spots; do not invent tests or runtime evidence.","required":true,"evidence":"sourced_inference"}],"sources":[{"source_id":"6c4f9167eb374f608bdd82cbd8a82a7d845fe20b88d57c7e7366763c05e2243f","alias_source_ids":["6c4f9167eb374f608bdd82cbd8a82a7d845fe20b88d57c7e7366763c05e2243f"],"path":"api.py","symbol":"load_repository","text":"@app.post("/load")
async def load_repository(request: LoadRepositoryRequest):
    """Load a repository"""
    fastcode = _ensure_fastcode_initialized()

    try:
        logger.info(f"Loading repository: {request.source}")
        fastcode.load_repository(request.source, request.is_url)

        return {
            "status": "success",
            "message": "Repository loaded successfully",
            "repo_info": fastcode.repo_info,
        }

    except Exception as e:
        logger.error(f"Failed to load repository: {e}")
        raise HTTPException(status_code=500, detail=str(e))"},{"source_id":"a97fd76745148e7c4cf04cd0fc6ef8a3f759b783ada1e4e66578165b20428ad0","alias_source_ids":["a97fd76745148e7c4cf04cd0fc6ef8a3f759b783ada1e4e66578165b20428ad0"],"path":"api.py","symbol":"load_and_index","text":"@app.post("/load-and-index")
async def load_and_index(request: LoadRepositoryRequest, force: bool = False):
    """Load and index repository in one call"""
    fastcode = _ensure_fastcode_initialized()

    try:
        logger.info(f"Loading repository: {request.source}")
        await asyncio.to_thread(fastcode.load_repository, request.source, request.is_url)

        logger.info("Indexing repository")
        await asyncio.to_thread(fastcode.index_repository, force=force)

        fastcode.vector_store.invalidate_scan_cache()

        return {
            "status": "success",
            "message": "Repository loaded and indexed successfully",
            "summary": fastcode.get_repository_summary(),
        }

    except Exception as e:
        logger.error(f"Failed to load and index: {e}")
        raise HTTPException(status_code=500, detail=str(e))"},{"source_id":"9ff64131bff3dc5629571f485b5ed9de696ddc09605310793c3ccdf0002e7a8b","alias_source_ids":["5f9569a610648c0d61bff9071eca675412ca5bdb1c6008fea9dd8ec78f472b25","9ff64131bff3dc5629571f485b5ed9de696ddc09605310793c3ccdf0002e7a8b"],"path":"fastcode/agent_tools.py","symbol":"AgentTools.search_codebase","text":"def search_codebase(self, search_term: str, file_pattern: str = "*", 
                       root_path: str = ".", max_results: int = 30,
                       case_sensitive: bool = False,
                       use_regex: bool = False) -> Dict[str, Any]:
        """
        Search for files containing specific strings or patterns

        Args:
            search_term: String or regex pattern to search for
            file_pattern: File pattern to match (e.g., "*.py", "*.js")
            root_path: Root path to start search (relative to repo root)
            max_results: Maximum number of matches to return
            case_sensitive: Whether search is case-sensitive
            use_regex: Whether to treat search_term as regex

        Returns:
            Dictionary with search results
        """
        # Security check
        self.logger.info(f"Searching codebase for term '{search_term}' "
                         f"in files matching '{file_pattern}' "
                         f"under '{root_path}' "
                         f"(case_sensitive={case_sensitive}, use_regex={use_regex}),"
                         f"working base path is {self.repo_root}")
        if not self._is_safe_path(root_path):
            return {
                "success": False,
                "error": f"Access denied: path outside repository root",
                "search_term": search_term
            }

        # Resolve path intelligently
        search_root = self._resolve_path(root_path)

        if search_root is None:
            return {
                "success": False,
                "error": f"Path does not exist: {root_path}",
                "search_term": search_term
            }
        try:
            # 1. Prepare search Pattern (moved out of loop)
            # -------------------------------------------------
            if use_regex:
                flags = 0 if case_sensitive else re.IGNORECASE
                try:
                    content_pattern = re.compile(search_term, flags)
                except re.error as e:
                    return {"success": False, "error": f"Invalid regex: {e}", "search_term": search_term}
            else:
                # Intelligently handle OR operation
                if '|' in search_term:
                    terms = [re.escape(t.strip()) for t in search_term.split('|')]
                    pattern_str = '|'.join(terms)
                else:
                    pattern_str = re.escape(search_term)
                flags = 0 if case_sensitive else re.IGNORECASE
                content_pattern = re.compile(pattern_str, flags)

            # 2. Prepare file path matching regex (moved out of loop and optimized)
            # -------------------------------------------------
            file_matcher = None
            normalized_file_pattern = file_pattern.lstrip('./').replace('\\', '/')

            # Define conversion function (Helper)
            def _compile_glob(pattern):
                # Convert glob (**/*.py) to regex
                parts = pattern.split('**')
                regex_parts = []
                for i, part in enumerate(parts):
                    if part:
                        # Use fnmatch to convert each part
                        part_regex = fnmatch.translate(part)
                        # Clean up trailing anchor (?ms) or \Z added by fnmatch
                        # Note: fnmatch output varies slightly across Python versions, universal cleanup method:
                        part_regex = re.sub(r'(\\Z(?:\(\?ms\))?|\\Z)$', '', part_regex)
                        regex_parts.append(part_regex)
                    if i < len(parts) - 1:
                        regex_parts.append('.*') # ** replaced with .*
                return re.compile('(?ms)' + ''.join(regex_parts) + r'\Z')

            if file_pattern != "*":
                try:
                    file_matcher = _compile_glob(normalized_file_pattern)
                except Exception as e:
                    self.logger.warning(f"Failed to compile file pattern '{file_pattern}', falling back to filename match. Error: {e}")
                    # file_matcher remains None, will be handled with fallback in loop

            results = []
            files_searched = 0

            # 3. Traverse files
            # -------------------------------------------------
            for root, dirs, files in os.walk(search_root):
                # Filter directories
                dirs[:] = [d for d in dirs if not d.startswith('.') and 
                        d not in ['__pycache__', 'node_modules', '.git', 'dist', 'build', 'venv']]

                for file in files:
                    if file.startswith('.'):
                        continue

                    file_path = os.path.join(root, file)

                    # [Key fix]: Calculate path relative to search_root for Pattern matching
                    # This way if user searches for "*.py" under "src", it can correctly match "main.py" in "src/main.py"
                    rel_to_search = os.path.relpath(file_path, search_root).replace(os.sep, '/')

                    # [For display]: Calculate path relative to Repo Root for returning results
                    rel_path_display = os.path.relpath(file_path, self.repo_root).replace(os.sep, '/')

                    # 4. File path matching logic
                    # -------------------------------------------------
                    match_file = False
                    if file_pattern == "*":
                        match_file = True
                    elif file_matcher:
                        # Try Regex matching first (match full path)
                        if file_matcher.match(rel_to_search):
                            match_file = True
                        # [Key fix]: If full path doesn't match, try matching just the filename
                        # This solves the case where user inputs "*.py" but rel_path is "subdir/file.py" (fnmatch usually handles this, but may be lost after regex conversion)
                        elif file_matcher.match(file):
                            match_file = True

                    # If regex conversion failed or no match, and no matcher, try original fnmatch as fallback
                    if not match_file and not file_matcher and file_pattern != "*":
                        if fnmatch.fnmatch(file, file_pattern) or fnmatch.fnmatch(rel_to_search, file_pattern):
                            match_file = True

                    if not match_file:
                        continue

                    files_searched += 1

                    # 5a. Filename/path match check
                    # -------------------------------------------------
                    filename_match = False
                    if use_regex:
                        if content_pattern.search(file) or content_pattern.search(rel_to_search):
                            filename_match = True
                    else:
                        if case_sensitive:
                            if search_term in file or search_term in rel_to_search:
                                filename_match = True
                        else:
                            search_lower = search_term.lower()
                            if search_lower in file.lower() or search_lower in rel_to_search.lower():
                                filename_match = True

                    # 5b. Content search
                    # -------------------------------------------------
                    try:
                        with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
                            content = f.read()

                        file_matches = []
                        lines = content.split('\n')

                        for i, line in enumerate(lines, 1):
                            if content_pattern.search(line):
                                file_matches.append({
                                    "line_number": i,
                                    "line_content": line.strip()[:200]
                                })
                                # Limit matches per file to prevent result explosion
                                if len(file_matches) >= 20:
                                    break

                        if file_matches or filename_match:
                            results.append({
                                "file": rel_path_display, # Return path relative to Repo to user
                                "match_count": len(file_matches),
                                "matches": file_matches,
                                "match_type": "both" if (file_matches and filename_match) else ("filename" if filename_match else "content")
                            })
                            if len(results) >= max_results:
                                break # Outer loop break requires logic control

                    except Exception:
                        # When content reading fails, still return if filename matches
                        if filename_match:
                            results.append({
                                "file": rel_path_display,
                                "match_count": 0,
                                "matches": [],
                                "match_type": "filename"
                            })
                            if len(results) >= max_results:
                                break
                        continue

                if len(results) >= max_results:
                    break

                # Auto-retry with recursive pattern if no results found
                # and pattern looks like it should be recursive (e.g., "dir/*.py" -> "dir/**/*.py")
            if len(results) == 0 and file_pattern != "*":
                # Check if pattern is non-recursive but could be made recursive
                if '**' not in file_pattern and '/' in file_pattern and '*' in file_pattern:
                    # Pattern like "src/_pytest/*.py" or "dir/subdir/*.ext"
                    # Try converting to recursive: "src/_pytest/**/*.py"
                    parts = file_pattern.rsplit('/', 1)
                    if len(parts) == 2:
                        dir_part, file_part = parts
                        recursive_pattern = f"{dir_part}/**/{file_part}"

                        self.logger.info(f"No results with pattern '{file_pattern}', "
                                    f"auto-retrying with recursive pattern '{recursive_pattern}'")

                        # Recursively call with the new pattern (only once, to avoid infinite loop)
                        return self.search_codebase(
                            search_term=search_term,
                            file_pattern=recursive_pattern,
                            root_path=root_path,
                            max_results=max_results,
                            case_sensitive=case_sensitive,
                            use_regex=use_regex
                        )

            # Add debug info if still no results found
            debug_info = {}
            if len(results) == 0:
                debug_info["files_searched"] = files_searched
                debug_info["search_root"] = rel_path_root = os.path.relpath(search_root, self.repo_root)
                if files_searched == 0:
                    debug_info["hint"] = "No files matched the file_pattern even after auto-retry with recursive pattern"
                else:
                    debug_info["hint"] = "Files were searched but no content matches found. Check search_term."

            return {
                "success": True,
                "search_term": search_term,
                "file_pattern": file_pattern,
                "files_searched": files_searched,
                "matches_found": len(results),
                "results": results,
                **debug_info
            }

        except Exception as e:
            self.logger.error(f"Error searching codebase: {e}")
            return {
                "success": False,
                "error": str(e),
                "search_term": search_term
            }"},{"source_id":"6e88811451cda06d0d7c8b87b79fde3880f897677a4c59d2e8b445cb70fabc30","alias_source_ids":["6e88811451cda06d0d7c8b87b79fde3880f897677a4c59d2e8b445cb70fabc30"],"path":"fastcode/answer_generator.py","symbol":"AnswerGenerator._truncate_context","text":"def _truncate_context(self, context: str, max_tokens: int) -> str:
        """Truncate context to fit within token limit"""
        return truncate_to_tokens(context, max_tokens, self.model)"},{"source_id":"64e53597abdf83d3827430a880cb98d05ad1364d9d46aca28b995d8e140a279e","alias_source_ids":["64e53597abdf83d3827430a880cb98d05ad1364d9d46aca28b995d8e140a279e"],"path":"fastcode/answer_generator.py","symbol":"AnswerGenerator._generate_openai","text":"def _generate_openai(self, prompt: str) -> str:
        """Generate answer using OpenAI"""
        if self.client is None:
            return "Error: OpenAI client not initialized"

        try:
            response = openai_chat_completion(
                self.client,
                model=self.model,
                messages=[{"role": "user", "content": prompt}],
                temperature=self.temperature,
                max_tokens=self.max_tokens,
            )

            # print("response: ", response)

            # Defensive checks because some providers may return partial/None payloads
            if not response or not getattr(response, "choices", None):
                raise ValueError(f"Empty response or no choices returned: {response}")
            first_choice = response.choices[0]
            message = getattr(first_choice, "message", None)
            content = getattr(message, "content", None) if message else None
            if content is None:
                raise ValueError(f"LLM response has no content: {response}")
            return content

        except Exception as e:
            self.logger.error(f"OpenAI API error: {e}")
            raise"},{"source_id":"e3e2f3413e163267a24a860ef94e98e87a611a4880628e0555a534f94402de10","alias_source_ids":["e3e2f3413e163267a24a860ef94e98e87a611a4880628e0555a534f94402de10"],"path":"fastcode/answer_generator.py","symbol":"AnswerGenerator._generate_openai_stream","text":"def _generate_openai_stream(self, prompt: str):
        """Generate answer using OpenAI with streaming"""
        if self.client is None:
            yield "Error: OpenAI client not initialized"
            return

        try:
            response = openai_chat_completion(
                self.client,
                model=self.model,
                messages=[{"role": "user", "content": prompt}],
                temperature=self.temperature,
                max_tokens=self.max_tokens,
                stream=True,
            )

            for chunk in response:
                if chunk.choices and len(chunk.choices) > 0:
                    delta = chunk.choices[0].delta
                    if hasattr(delta, 'content') and delta.content:
                        yield delta.content

        except Exception as e:
            self.logger.error(f"OpenAI streaming API error: {e}")
            yield f"\n\nError: {str(e)}""},{"source_id":"7dbc6309168db0b0fdf528caeb2dd6ee65b604ae89d35cd3160bb3c9816f8c96","alias_source_ids":["7dbc6309168db0b0fdf528caeb2dd6ee65b604ae89d35cd3160bb3c9816f8c96"],"path":"fastcode/answer_generator.py","symbol":"AnswerGenerator._generate_anthropic","text":"def _generate_anthropic(self, prompt: str) -> str:
        """Generate answer using Anthropic Claude"""
        if self.client is None:
            return "Error: Anthropic client not initialized"

        try:
            response = self.client.messages.create(
                model=self.model,
                max_tokens=self.max_tokens,
                temperature=self.temperature,
                messages=[{"role": "user", "content": prompt}]
            )

            # Defensive checks because some providers may return partial/None payloads
            if not response or not getattr(response, "content", None):
                raise ValueError(f"Empty response or no content returned: {response}")
            first_block = response.content[0] if response.content else None
            text = getattr(first_block, "text", None) if first_block else None
            if text is None:
                raise ValueError(f"LLM response has no text: {response}")
            return text

        except Exception as e:
            self.logger.error(f"Anthropic API error: {e}")
            raise"},{"source_id":"4c2bdef3d031d1e22c45de1bec93f183c88aa6aa935f8cf5357a8fc871f31fd0","alias_source_ids":["4c2bdef3d031d1e22c45de1bec93f183c88aa6aa935f8cf5357a8fc871f31fd0"],"path":"fastcode/answer_generator.py","symbol":"AnswerGenerator._generate_anthropic_stream","text":"def _generate_anthropic_stream(self, prompt: str):
        """Generate answer using Anthropic Claude with streaming"""
        if self.client is None:
            yield "Error: Anthropic client not initialized"
            return

        try:
            with self.client.messages.stream(
                model=self.model,
                max_tokens=self.max_tokens,
                temperature=self.temperature,
                messages=[{"role": "user", "content": prompt}]
            ) as stream:
                for text in stream.text_stream:
                    yield text

        except Exception as e:
            self.logger.error(f"Anthropic streaming API error: {e}")
            yield f"\n\nError: {str(e)}""},{"source_id":"b4bfe0ab6039235896cf6b6adcac523538b8640aa8e9f9cd93dc608b92991612","alias_source_ids":["b4bfe0ab6039235896cf6b6adcac523538b8640aa8e9f9cd93dc608b92991612"],"path":"fastcode/answer_generator.py","symbol":"AnswerGenerator.format_answer_with_sources","text":"def format_answer_with_sources(self, result: Dict[str, Any]) -> str:
        """Format answer with sources for display"""
        output = []

        # Add answer
        output.append("## Answer\n")
        output.append(result.get("answer", ""))

        # Add sources
        sources = result.get("sources", [])
        if sources:
            output.append("\n\n## Sources\n")
            for i, source in enumerate(sources, 1):
                repo_info = f"[{source['repository']}] " if source.get('repository') else ""
                output.append(
                    f"{i}. {repo_info}**{source['name']}** ({source['type']}) "
                    f"in `{source['file']}` (lines {source['lines']}) "
                    f"- Relevance: {source['score']:.2f}"
                )

        # Add metadata
        if "prompt_tokens" in result:
            output.append(f"\n\n*Used {result['prompt_tokens']} prompt tokens, "
                         f"{result.get('context_elements', 0)} code snippets*")

        return "\n".join(output)"},{"source_id":"7e4a7532e153f56adbfe952f9d7636bed8e38bd2b2d93a67a70b78c935cb8a2e","alias_source_ids":["7e4a7532e153f56adbfe952f9d7636bed8e38bd2b2d93a67a70b78c935cb8a2e"],"path":"fastcode/cache.py","symbol":"CacheManager._generate_key","text":"def _generate_key(self, prefix: str, *args) -> str:
        """Generate cache key from arguments"""
        # Create a hash of all arguments
        content = "_".join(str(arg) for arg in args)
        hash_val = hashlib.md5(content.encode()).hexdigest()
        return f"{prefix}_{hash_val}""},{"source_id":"e9753ab17fb867d43e387688e2908ea97ef5c366fed91bc9f448044db3e533df","alias_source_ids":["e9753ab17fb867d43e387688e2908ea97ef5c366fed91bc9f448044db3e533df"],"path":"fastcode/cache.py","symbol":"CacheManager.get_query_result","text":"def get_query_result(self, query: str, repo_hash: str) -> Optional[Any]:
        """Get cached query result"""
        if not self.cache_queries:
            return None
        key = self._generate_key("query", query, repo_hash)
        return self.get(key)"},{"source_id":"249e265dffeed80e70ab57332414e6404c9e24392611d069df3bc3cd8bfb144c","alias_source_ids":["249e265dffeed80e70ab57332414e6404c9e24392611d069df3bc3cd8bfb144c"],"path":"fastcode/cache.py","symbol":"CacheManager.set_query_result","text":"def set_query_result(self, query: str, repo_hash: str, result: Any) -> bool:
        """Cache query result"""
        if not self.cache_queries:
            return False
        key = self._generate_key("query", query, repo_hash)
        return self.set(key, result)"},{"source_id":"18bd1442ebf14ca13388be94fcc2884400bbcbd9d893e24058b3934245f40f20","alias_source_ids":["18bd1442ebf14ca13388be94fcc2884400bbcbd9d893e24058b3934245f40f20"],"path":"fastcode/cache.py","symbol":"CacheManager.save_dialogue_turn","text":"def save_dialogue_turn(self, session_id: str, turn_number: int,
                           query: str, answer: str, summary: str,
                           retrieved_elements: Optional[List[Dict[str, Any]]] = None,
                           metadata: Optional[Dict[str, Any]] = None) -> bool:
        """
        Save a single dialogue turn to cache

        Args:
            session_id: Unique session identifier
            turn_number: Turn number (1-indexed)
            query: User query
            answer: Generated answer
            summary: Brief summary of the dialogue turn
            retrieved_elements: Retrieved code elements (optional)
            metadata: Additional metadata (optional)

        Returns:
            True if successful, False otherwise
        """
        if not self.enabled:
            return False

        try:
            # Create turn data
            turn_data = {
                "session_id": session_id,
                "turn_number": turn_number,
                "timestamp": time.time(),
                "query": query,
                "answer": answer,
                "summary": summary,
                "retrieved_elements": retrieved_elements or [],
                "metadata": metadata or {}
            }

            # Generate key
            key = f"dialogue_{session_id}_turn_{turn_number}"

            # Save to cache (with longer TTL for dialogue history)
            # Use configurable dialogue_ttl instead of hardcoded value
            self.set(key, turn_data, ttl=self.dialogue_ttl)

            # Update session index (propagate multi_turn flag from metadata)
            multi_turn = (metadata or {}).get("multi_turn")
            self._update_session_index(session_id, turn_number, multi_turn=multi_turn)

            self.logger.debug(f"Saved dialogue turn: {session_id} turn {turn_number}")
            return True

        except Exception as e:
            self.logger.error(f"Failed to save dialogue turn: {e}")
            return False"},{"source_id":"1c392dc661ba7f04ac88c3042e9f20b53907d10dee4164617e0d6f2a1c8623cf","alias_source_ids":["1c392dc661ba7f04ac88c3042e9f20b53907d10dee4164617e0d6f2a1c8623cf"],"path":"fastcode/cache.py","symbol":"CacheManager.get_recent_summaries","text":"def get_recent_summaries(self, session_id: str, num_rounds: int) -> List[Dict[str, Any]]:
        """
        Get recent dialogue summaries for context

        Args:
            session_id: Session identifier
            num_rounds: Number of recent rounds to retrieve

        Returns:
            List of summary data with turn_number, query, and summary
        """
        if not self.enabled:
            return []

        try:
            history = self.get_dialogue_history(session_id, max_turns=num_rounds)

            summaries = []
            for turn in history:
                summaries.append({
                    "turn_number": turn.get("turn_number"),
                    "query": turn.get("query"),
                    "summary": turn.get("summary"),
                })

            return summaries

        except Exception as e:
            self.logger.error(f"Failed to get recent summaries: {e}")
            return []"},{"source_id":"9c366606c9251c368dc4e9b8767f49519a3c0e4b98354ab7a57d34bcf0c9c013","alias_source_ids":["9c366606c9251c368dc4e9b8767f49519a3c0e4b98354ab7a57d34bcf0c9c013"],"path":"fastcode/cache.py","symbol":"CacheManager._get_session_index","text":"def _get_session_index(self, session_id: str) -> Optional[Dict[str, Any]]:
        """Get session index"""
        key = f"dialogue_session_{session_id}_index"
        return self.get(key)"},{"source_id":"0c7aa1f17802658fd8f479572794f6eb00095f3eb6e7a55d17ced456b50ed1b5","alias_source_ids":["0c7aa1f17802658fd8f479572794f6eb00095f3eb6e7a55d17ced456b50ed1b5"],"path":"fastcode/call_extractor.py","symbol":"CallExtractor._execute_query","text":"def _execute_query(self, query: Query, node: tree_sitter.Node) -> List[Any]:
        """
        Execute Tree-sitter query and return captures in standardized format.

        Args:
            query: Tree-sitter Query object
            node: Root node for query execution

        Returns:
            List of (node, capture_name) tuples
        """
        try:
            cursor = QueryCursor(query)
            captures = cursor.captures(node)

            # Handle different tree-sitter versions
            # Older versions return dict, newer versions return list
            if isinstance(captures, dict):
                # Convert dict format to list of (node, capture_name) tuples
                result = []
                for capture_name, nodes in captures.items():
                    for node in nodes:
                        result.append((node, capture_name))
                return result
            else:
                # Newer versions already return list format
                return captures

        except Exception as e:
            self.logger.error(f"Failed to execute query: {e}")
            return []"},{"source_id":"897f7b966d657cf5f9e3a433f57beb45ab165e7daf8b7db777477812acb0a74e","alias_source_ids":["897f7b966d657cf5f9e3a433f57beb45ab165e7daf8b7db777477812acb0a74e"],"path":"fastcode/embedder.py","symbol":"CodeEmbedder.compute_similarities","text":"def compute_similarities(self, query_embedding: np.ndarray, 
                            embeddings: np.ndarray) -> np.ndarray:
        """
        Compute similarities between query and multiple embeddings

        Args:
            query_embedding: Query embedding vector
            embeddings: Array of embedding vectors

        Returns:
            Array of similarity scores
        """
        if self.normalize:
            # Simple dot product for normalized embeddings
            similarities = np.dot(embeddings, query_embedding)
        else:
            # Compute cosine similarities
            norms = np.linalg.norm(embeddings, axis=1)
            query_norm = np.linalg.norm(query_embedding)
            if query_norm == 0:
                return np.zeros(len(embeddings))
            similarities = np.dot(embeddings, query_embedding) / (norms * query_norm)

        return similarities"},{"source_id":"9df6d620f7766f055d22605b11e287c285981a594a7aa2edf5ed40d82702568b","alias_source_ids":["9df6d620f7766f055d22605b11e287c285981a594a7aa2edf5ed40d82702568b"],"path":"fastcode/graph_builder.py","symbol":"CodeGraphBuilder._get_module_path_from_file_id","text":"def _get_module_path_from_file_id(self, file_id: str, elements: List[CodeElement], repo_root: str) -> Optional[str]:
        """
        Get module path from file ID by looking up the corresponding CodeElement.

        Args:
            file_id: File element ID
            elements: List of all code elements for lookup
            repo_root: Repository root path for module path conversion

        Returns:
            Module path (e.g., "app.services.auth") or None if not found
        """
        # Find the file element by ID
        for elem in elements:
            if elem.id == file_id and elem.type == "file":
                # Use the element's file_path to generate module path
                return file_path_to_module_path(elem.file_path, repo_root)

        return None"},{"source_id":"a8f62f0083e424b3040b89ae0b66c4ea0c393149f664bb4bfe141baa5fa4be7e","alias_source_ids":["a8f62f0083e424b3040b89ae0b66c4ea0c393149f664bb4bfe141baa5fa4be7e"],"path":"fastcode/graph_builder.py","symbol":"CodeGraphBuilder.save","text":"def save(self, name: str = "index"):
        """
        Save graph data to disk

        Args:
            name: Name for the saved files
        """
        graph_path = os.path.join(self.persist_dir, f"{name}_graphs.pkl")

        try:
            with open(graph_path, 'wb') as f:
                pickle.dump({
                    "call_graph": self.call_graph,
                    "dependency_graph": self.dependency_graph,
                    "inheritance_graph": self.inheritance_graph,
                    "element_by_name": {k: v.to_dict() for k, v in self.element_by_name.items()},
                    "element_by_id": {k: v.to_dict() for k, v in self.element_by_id.items()},
                    "imports_by_file": self.imports_by_file,
                }, f)

            self.logger.info(f"Saved graph data to {graph_path}")
            return True

        except Exception as e:
            self.logger.error(f"Failed to save graph data: {e}")
            return False"},{"source_id":"2dff45803c5c2609981a1dac4cbdcbf1f712a465199acef081018a2e3712cfde","alias_source_ids":["2dff45803c5c2609981a1dac4cbdcbf1f712a465199acef081018a2e3712cfde"],"path":"fastcode/indexer.py","symbol":"CodeIndexer.index_files","text":"def index_files(self, file_infos: List[Dict], repo_name: str,
                    repo_url: str = None) -> List[CodeElement]:
        """Index specific files only (for incremental reindexing).

        Reuses existing _index_file() and embedding pipeline.
        Skips repo overview generation (already exists for this repo).

        Args:
            file_infos: List of file info dicts from loader.scan_files()
            repo_name: Repository name for element IDs
            repo_url: Optional repository URL

        Returns:
            List of CodeElement objects with embeddings
        """
        self.current_repo_name = repo_name
        self.current_repo_url = repo_url
        self.elements = []

        for file_info in file_infos:
            file_path = file_info["path"]

            content = self.loader.read_file_content(file_path)
            if content is None:
                continue

            parse_result = self.parser.parse_file(file_path, content)
            if parse_result is None:
                continue

            self._index_file(file_info, content, parse_result)

        self.logger.info(f"Parsed {len(self.elements)} elements from {len(file_infos)} changed files")

        # Generate embeddings for new elements only
        if self.elements:
            element_dicts = [elem.to_dict() for elem in self.elements]
            elements_with_embeddings = self.embedder.embed_code_elements(element_dicts)

            for elem, elem_dict in zip(self.elements, elements_with_embeddings):
                elem.metadata["embedding"] = elem_dict.get("embedding")
                elem.metadata["embedding_text"] = elem_dict.get("embedding_text")

        return self.elements"},{"source_id":"642c534af2790d8a412d714b768f7ecc51ce50b73445214e9221373de49fe2d4","alias_source_ids":["642c534af2790d8a412d714b768f7ecc51ce50b73445214e9221373de49fe2d4"],"path":"fastcode/indexer.py","symbol":"CodeIndexer._generate_file_summary","text":"def _generate_file_summary(self, parse_result: FileParseResult) -> str:
        """Generate summary for a file"""
        parts = []

        if parse_result.module_docstring:
            # Use first line of docstring
            first_line = parse_result.module_docstring.split("\n")[0]
            parts.append(first_line)

        # Add class/function counts
        if parse_result.classes:
            parts.append(f"{len(parse_result.classes)} classes")
        if parse_result.functions:
            parts.append(f"{len(parse_result.functions)} functions")

        # Add language
        parts.append(f"{parse_result.language} file")

        return ", ".join(parts) if parts else f"{parse_result.language} source file""},{"source_id":"328f190953c5863c4d71edb493a7703258c85ece1af72c9edaa8dd2299659f3d","alias_source_ids":["328f190953c5863c4d71edb493a7703258c85ece1af72c9edaa8dd2299659f3d"],"path":"fastcode/indexer.py","symbol":"CodeIndexer._generate_id","text":"def _generate_id(self, type_: str, *parts: str) -> str:
        """
        Generate deterministic unique ID for code element using hashing.
        Format: {repo}_{type}_{hash(path+identifier)}
        """
        repo_prefix = normalize_path(self.current_repo_name) if self.current_repo_name else "default"
        unique_string = f"{repo_prefix}/{type_}/{'/'.join(str(p) for p in parts)}"

        hash_suffix = hashlib.md5(unique_string.encode("utf-8")).hexdigest()[:16]

        return f"{repo_prefix}_{type_}_{hash_suffix}""},{"source_id":"2ef330ac97d04d38853a9467f4213be4500b760d8383eca353a816ec620057d3","alias_source_ids":["2ef330ac97d04d38853a9467f4213be4500b760d8383eca353a816ec620057d3"],"path":"fastcode/iterative_agent.py","symbol":"IterativeAgent._initialize_adaptive_parameters","text":"def _initialize_adaptive_parameters(self, query_complexity: int):
        """
        Initialize adaptive parameters based on query and repo complexity

        Args:
            query_complexity: Query complexity score (0-100)
        """
        # Calculate repo complexity factor
        repo_factor = self._calculate_repo_factor()

        # Adaptive max iterations: scales with complexity
        # Simple query in simple repo: 2-3 iterations
        # Complex query in complex repo: 4-5 iterations
        complexity_score = (query_complexity / 100 + repo_factor) / 2
        self.max_iterations = max(2, min(6, int(self.base_max_iterations * (0.7 + complexity_score * 0.6))))

        # Adaptive confidence threshold: more complex queries can accept slightly lower confidence
        # to avoid over-iteration when perfect confidence is hard to achieve
        if query_complexity >= 80:
            # Very complex: accept 90% confidence
            self.confidence_threshold = max(90, self.base_confidence_threshold - 5)
        elif query_complexity >= 60:
            # Moderately complex: accept 92% confidence
            self.confidence_threshold = max(92, self.base_confidence_threshold - 3)
        else:
            # Simple: maintain high standard
            self.confidence_threshold = self.base_confidence_threshold

        # Adaptive line budget: scales with complexity
        # Simple queries: smaller budget to force conciseness
        # Complex queries: larger budget to allow thorough exploration
        if query_complexity <= 30:
            self.adaptive_line_budget = int(self.max_total_lines * 0.6)  # 6000 lines
        elif query_complexity <= 60:
            self.adaptive_line_budget = int(self.max_total_lines * 0.8)  # 8000 lines
        else:
            self.adaptive_line_budget = int(self.max_total_lines * 1.0 * repo_factor)  # Up to 20000 lines for very complex

        self.logger.info(
            f"Adaptive parameters set: max_iterations={self.max_iterations}, "
            f"confidence_threshold={self.confidence_threshold}, "
            f"line_budget={self.adaptive_line_budget}, "
            f"query_complexity={query_complexity}, repo_factor={repo_factor:.2f}"
        )"},{"source_id":"7a8f6ee0a73ec62b07c2dfddb4314b98777920798c7a71aad0ac4817b32d9257","alias_source_ids":["7a8f6ee0a73ec62b07c2dfddb4314b98777920798c7a71aad0ac4817b32d9257"],"path":"fastcode/iterative_agent.py","symbol":"IterativeAgent._round_one","text":"def _round_one(self, query: str, processed_query, query_info: Dict[str, Any],
                   repo_filter: Optional[List[str]] = None,
                   dialogue_history: Optional[List[Dict[str, Any]]] = None) -> Dict[str, Any]:
        """
        Round 1: Initial assessment without any file content

        Returns:
            Dict with:
            - confidence: int (0-100)
            - query_complexity: int (0-100)
            - tool_calls: List[Dict] (if confidence < 95)
            - query_enhancement_params: Dict (if needed)
            - should_answer_directly: bool
        """
        self.logger.info("Round 1: Initial assessment")

        # Build prompt for round 1 (with dialogue history if available)
        prompt = self._build_round_one_prompt(query, processed_query, query_info, repo_filter, dialogue_history)

        # Call LLM
        response = self._call_llm(prompt)

        # Parse response
        result = self._parse_round_one_response(response)

        return result"},{"source_id":"826bd57212c55fcbbf168575befeb53900f94c83e9379194222f55b1f21f9039","alias_source_ids":["826bd57212c55fcbbf168575befeb53900f94c83e9379194222f55b1f21f9039"],"path":"fastcode/iterative_agent.py","symbol":"IterativeAgent._parse_query_enhancement_fallback.clean_markdown","text":"def clean_markdown(text: str) -> str:
            text = re.sub(r'\*\*([^*]+)\*\*', r'\1', text)
            text = re.sub(r'\*([^*]+)\*', r'\1', text)
            text = re.sub(r'`([^`]+)`', r'\1', text)
            text = text.replace('`', '')
            text = text.strip('*').strip()
            return text"},{"source_id":"aee35ad795f8361d1540282746cc49ad71792226fd14bd6c913d0d8a88155e45","alias_source_ids":["aee35ad795f8361d1540282746cc49ad71792226fd14bd6c913d0d8a88155e45"],"path":"fastcode/iterative_agent.py","symbol":"IterativeAgent._perform_standard_retrieval","text":"def _perform_standard_retrieval(self, processed_query, filters, repo_filter):
        """
        Perform standard retrieval without triggering iterative mode recursion
        Directly calls retriever's internal methods (_semantic_search, _keyword_search, etc.)
        instead of the top-level retrieve() method which would detect iterative mode
        and cause infinite recursion.

        IMPORTANT: Do NOT call self.retriever.retrieve() here - use internal methods only
        """
        self.logger.info("Performing standard retrieval (bypass iterative mode)")

        # Get query text
        if hasattr(processed_query, 'rewritten_query') and processed_query.rewritten_query:
            search_text = processed_query.rewritten_query
        else:
            search_text = processed_query.original if hasattr(processed_query, 'original') else str(processed_query)

        keywords = processed_query.keywords if hasattr(processed_query, 'keywords') else []
        pseudocode = processed_query.pseudocode_hints if hasattr(processed_query, 'pseudocode_hints') else None

        self.logger.debug(f"Search text: {search_text[:100]}...")

        # Stage 1: Semantic search
        semantic_results = self.retriever._semantic_search(search_text, top_k=20, repo_filter=repo_filter)

        # Stage 2: Pseudocode search (if available)
        pseudocode_results = []
        if pseudocode:
            pseudocode_results = self.retriever._semantic_search(pseudocode, top_k=10, repo_filter=repo_filter)

        # Stage 3: Keyword search
        keyword_query = " ".join(keywords) if keywords else search_text
        keyword_results = self.retriever._keyword_search(keyword_query, top_k=10, repo_filter=repo_filter)

        # Stage 4: Combine results
        combined_results = self.retriever._combine_results(
            semantic_results, keyword_results, pseudocode_results
        )

        # Stage 5: Re-rank
        final_results = self.retriever._rerank(search_text, combined_results)

        # # Stage 6: Apply filters
        # if filters:
        #     final_results = self.retriever._apply_filters(final_results, filters)

        # Stage 7: Diversification
        final_results = self.retriever._diversify(final_results)

        # Limit results
        max_results = self.retriever.max_results
        final_results = final_results[:max_results]

        return final_results"},{"source_id":"56980827fe33e90791a0bc2640c6f656a90a69fc6481d71e35774ac4d8dd174f","alias_source_ids":["56980827fe33e90791a0bc2640c6f656a90a69fc6481d71e35774ac4d8dd174f"],"path":"fastcode/iterative_agent.py","symbol":"IterativeAgent._filter_new_elements","text":"def _filter_new_elements(self, existing: List[Dict[str, Any]],
                             candidates: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
        """Filter candidates to only those not present in existing."""
        if not candidates:
            return []
        existing_keys = {self._element_identity(elem) for elem in existing}
        filtered = []
        for elem in candidates:
            key = self._element_identity(elem)
            if key in existing_keys:
                continue
            filtered.append(elem)
        return filtered"},{"source_id":"71c90eccc173fe2e7a60c010d59f94b243712c53b4c6fa75c4d7f5bc3e59063f","alias_source_ids":["71c90eccc173fe2e7a60c010d59f94b243712c53b4c6fa75c4d7f5bc3e59063f","ccb70a759faf3c9c39593b80078f5a5d01ee8482c44a449e79b7fd7e7e0e0743"],"path":"fastcode/iterative_agent.py","symbol":"IterativeAgent._should_continue_iteration","text":"def _should_continue_iteration(self, current_round: int, confidence: int,
                                   current_elements: List[Dict[str, Any]],
                                   query_complexity: int) -> bool:
        """
        Decide whether to continue iteration based on intelligent cost-benefit analysis

        Considers:
        1. Confidence gap to threshold
        2. Code lines vs budget
        3. Historical confidence gains (ROI) - ADAPTIVE
        4. Stagnation (flatline)
        5. Hard limits

        Returns:
            True if should continue, False otherwise
        """
        # Check 1: Confidence already sufficient
        if confidence >= self.confidence_threshold:
            self.logger.info(f"Stopping: confidence {confidence} >= threshold {self.confidence_threshold}")
            return False

        # Check 2: Hard iteration limit
        if current_round >= self.max_iterations:
            self.logger.info(f"Stopping: reached max iterations {self.max_iterations}")
            return False

        # Check 3: Line budget check
        total_lines = self._calculate_total_lines(current_elements)
        if total_lines >= self.adaptive_line_budget:
            self.logger.info(f"Stopping: exceeded line budget ({total_lines} >= {self.adaptive_line_budget})")
            return False

        # Check 4: Adaptive Trend & ROI Analysis (Revised)
        # Logic: 
        # - Confidence Drop -> Continue (Useful info found), unless consecutive drops.
        # - Low ROI (Inefficient Rise) -> Continue, unless consecutive low efficiency.
        # - Stagnation (No change) -> Stop.

        if len(self.iteration_history) >= 2:
            current_metrics = self.iteration_history[-1]
            current_gain = current_metrics["confidence_gain"]
            current_roi = current_metrics["roi"]

            # 4a. Stagnation Check (Priority: High)
            # If fluctuations are very small (up or down)
            if abs(current_gain) < 1.0: 
                 if len(self.iteration_history) >= 3:
                      prev_gain = self.iteration_history[-2]["confidence_gain"]
                      if abs(prev_gain) < 1.0:
                          self.logger.info("Stopping: Stagnation detected (consecutive small fluctuations).")
                          return False

            # Helper to determine if a round was "Low Performance"
            # Low Performance = Significant Drop OR (Small Gain AND Low ROI)
            def is_low_performance(gain, roi, query_comp, curr_conf):
                min_roi = self._get_min_roi_threshold(query_comp, curr_conf)
                # Condition 1: Significant Drop (negative gain)
                # Note: User says drop is "useful info", so we don't treat single drop as "Stop condition".
                # But consecutive drops is bad.
                if gain < -1.0: 
                    return True

                # Condition 2: Low Efficiency (Small positive gain AND Low ROI)
                # If gain is small (but > -1) and ROI is low
                if -1.0 <= gain < self.min_confidence_gain and roi < min_roi:
                    return True

                return False

            # Check current performance
            current_is_low = is_low_performance(current_gain, current_roi, query_complexity, confidence)

            if current_is_low:
                # If current is low, check if previous was also low
                if len(self.iteration_history) >= 3:
                     prev_metrics = self.iteration_history[-2]
                     prev_gain = prev_metrics["confidence_gain"]
                     prev_roi = prev_metrics["roi"]
                     prev_conf = prev_metrics["confidence"]

                     if is_low_performance(prev_gain, prev_roi, query_complexity, prev_conf):
                         self.logger.info(f"Stopping: Consecutive low performance rounds (Current Gain: {current_gain:.1f}, Prev Gain: {prev_gain:.1f}).")
                         return False

                     # Not consecutive, so we continue to explore
                     self.logger.info(f"Continuing: Low performance this round ({current_gain:.1f}), but allowing adaptive exploration.")
                else:
                    # First iterative round resulted in low performance.
                    # We should probably allow one more chance as it's the start of iteration.
                    self.logger.info(f"Continuing: First iterative round low performance ({current_gain:.1f}), allowing exploration.")

        # Check 5: Strict Stagnation (last 3 rounds) - Keep as safeguard
        if len(self.iteration_history) >= 3:
            last_three_confidences = [h["confidence"] for h in self.iteration_history[-3:]]
            if max(last_three_confidences) - min(last_three_confidences) < 2:
                self.logger.info(f"Stopping: confidence stagnation detected ({last_three_confidences})")
                return False

        # Check 6: Cost-benefit threshold
        confidence_gap = self.confidence_threshold - confidence
        remaining_line_budget = self.adaptive_line_budget - total_lines

        # Estimate if we can close the confidence gap with remaining budget
        estimated_lines_needed = confidence_gap * 100  # Conservative estimate

        if estimated_lines_needed > remaining_line_budget * 1.5:
            # Relax budget check if we just had a drop (exploration mode)
            if len(self.iteration_history) >= 2 and self.iteration_history[-1]["confidence_gain"] < 0:
                 self.logger.info("Relaxing budget check due to confidence drop (exploration mode).")
            else:
                self.logger.info(
                    f"Stopping: unlikely to reach target confidence "
                    f"(need ~{estimated_lines_needed} lines, have {remaining_line_budget})"
                )
                return False

        # All checks passed, continue iteration
        self.logger.info(
            f"Continuing: confidence_gap={confidence_gap}, "
            f"lines={total_lines}/{self.adaptive_line_budget}, "
            f"round={current_round}/{self.max_iterations}"
        )
        return True"},{"source_id":"8909f58dae7387a2797c675c5dc228ad158930b702aa4c0bcf2cdc773640b200","alias_source_ids":["8909f58dae7387a2797c675c5dc228ad158930b702aa4c0bcf2cdc773640b200"],"path":"fastcode/iterative_agent.py","symbol":"IterativeAgent._get_min_roi_threshold","text":"def _get_min_roi_threshold(self, query_complexity: int, current_confidence: int) -> float:
        """
        Get minimum acceptable ROI threshold based on query complexity and current confidence

        Returns:
            Minimum ROI (confidence gain per 1000 lines)
        """
        # Base ROI threshold
        base_roi = 2.0  # At least 2% confidence gain per 1000 lines

        # Adjust for query complexity (complex queries: accept lower ROI)
        if query_complexity >= 80:
            complexity_factor = 0.5
        elif query_complexity >= 60:
            complexity_factor = 0.7
        else:
            complexity_factor = 1.0

        # Adjust for current confidence (higher confidence: demand higher ROI)
        if current_confidence >= 85:
            confidence_factor = 1.5  # Demand more efficiency when close to target
        elif current_confidence >= 70:
            confidence_factor = 1.0
        else:
            confidence_factor = 0.8  # More lenient when starting low

        return base_roi * complexity_factor * confidence_factor"},{"source_id":"1673aadbb35cc07ad09c79d6c0dabb91e01f1e75dbfa43ae6997a3a94ef78710","alias_source_ids":["1673aadbb35cc07ad09c79d6c0dabb91e01f1e75dbfa43ae6997a3a94ef78710"],"path":"fastcode/iterative_agent.py","symbol":"IterativeAgent._generate_directory_tree._add_dir_to_tree","text":"def _add_dir_to_tree(path: str, prefix: str = "", depth: int = 0):
            if depth >= max_depth:
                return

            try:
                # List items
                if not os.path.exists(path) or not os.path.isdir(path):
                    return

                items = os.listdir(path)
                # Filter for directories only and remove ignored ones
                dirs = [d for d in items 
                       if os.path.isdir(os.path.join(path, d)) 
                       and d not in ignore_dirs 
                       and not d.startswith('.')]
                dirs.sort()

                for i, d in enumerate(dirs):
                    is_last = (i == len(dirs) - 1)
                    connector = "└── " if is_last else "├── "

                    tree_lines.append(f"{prefix}{connector}{d}/")

                    # Recurse
                    new_prefix = prefix + ("    " if is_last else "│   ")
                    _add_dir_to_tree(os.path.join(path, d), new_prefix, depth + 1)

            except Exception as e:
                # Silently fail for individual directories to keep output clean
                pass"},{"source_id":"f30079af74f72d237599ee302df22093afc8fcfcef16cff1f5f54a8adeaf237a","alias_source_ids":["f30079af74f72d237599ee302df22093afc8fcfcef16cff1f5f54a8adeaf237a"],"path":"fastcode/loader.py","symbol":"RepositoryLoader._prepare_repo_path","text":"def _prepare_repo_path(self, repo_name: str, target_dir: Optional[str] = None) -> str:
        """Prepare destination path under repository workspace."""
        base_dir = target_dir or self.safe_repo_root
        base_dir = os.path.abspath(base_dir)
        ensure_dir(base_dir)
        repo_path = os.path.join(base_dir, repo_name)

        if os.path.exists(repo_path):
            self._backup_existing_repo(repo_path)

        return repo_path"},{"source_id":"3ea8337a4cc79f1c2bcb7141801a9fd23b61a3ed19eae6baa193e997c63c4aad","alias_source_ids":["3ea8337a4cc79f1c2bcb7141801a9fd23b61a3ed19eae6baa193e997c63c4aad"],"path":"fastcode/loader.py","symbol":"RepositoryLoader.load_from_path","text":"def load_from_path(self, path: str, target_dir: Optional[str] = None) -> str:
        """
        Copy local repository into repository workspace and load it.

        Args:
            path: Local path to repository
            target_dir: Optional destination root (defaults to configured repo_root)

        Returns:
            Path to copied repository
        """
        if not os.path.exists(path):
            raise ValueError(f"Path does not exist: {path}")

        if not os.path.isdir(path):
            raise ValueError(f"Path is not a directory: {path}")

        source_path = os.path.abspath(path)
        self.repo_name = os.path.basename(source_path)
        destination_root = os.path.abspath(target_dir) if target_dir else self.safe_repo_root
        destination_path = os.path.join(destination_root, self.repo_name)

        # If source is already in workspace destination, use it directly.
        if os.path.abspath(source_path) == os.path.abspath(destination_path):
            self.repo_path = source_path
            self.logger.info(f"Loaded repository from workspace path {self.repo_path}")
            return self.repo_path

        self.repo_path = self._prepare_repo_path(self.repo_name, target_dir)

        # Copy entire working tree, including untracked files.
        shutil.copytree(source_path, self.repo_path, symlinks=True)

        self.logger.info(f"Copied repository from {source_path} to {self.repo_path}")
        return self.repo_path"},{"source_id":"2df7bac8e65ce821ed4434c09af61aaf2d5277711ee3f9c3302bf8fdb193584a","alias_source_ids":["2df7bac8e65ce821ed4434c09af61aaf2d5277711ee3f9c3302bf8fdb193584a"],"path":"fastcode/loader.py","symbol":"RepositoryLoader.get_repository_info","text":"def get_repository_info(self) -> Dict[str, Any]:
        """
        Get repository metadata

        Returns:
            Dictionary with repository information
        """
        if not self.repo_path:
            raise RuntimeError("No repository loaded")

        info = {
            "name": self.repo_name,
            "path": self.repo_path,
        }

        # Try to get git info
        try:
            repo = Repo(self.repo_path)
            info.update({
                "branch": repo.active_branch.name,
                "commit": repo.head.commit.hexsha[:8],
                "remote_url": repo.remotes.origin.url if repo.remotes else None,
            })
        except Exception:
            self.logger.debug("Not a git repository or git info unavailable")

        # Count files
        files = self.scan_files()
        info.update({
            "file_count": len(files),
            "total_size_mb": sum(f["size"] for f in files) / 1024 / 1024,
        })

        return info"},{"source_id":"3c55fe0f547e22c5019fbc6f09e537128205c4c3869ffd8eae3d0a204694f60c","alias_source_ids":["3c55fe0f547e22c5019fbc6f09e537128205c4c3869ffd8eae3d0a204694f60c"],"path":"fastcode/main.py","symbol":"FastCode.query","text":"def query(self, question: str, filters: Optional[Dict[str, Any]] = None, 
              repo_filter: Optional[List[str]] = None,
              session_id: Optional[str] = None,
              enable_multi_turn: Optional[bool] = None,
              use_agency_mode: Optional[bool] = None,
              prompt_builder: Optional[Callable[[str, str, Optional[Dict[str, Any]], Optional[List[Dict[str, Any]]]], str]] = None) -> Dict[str, Any]:
        """
        Query the repository (or multiple repositories)

        Args:
            question: User question
            filters: Optional filters for retrieval
            repo_filter: Optional list of repository names to search in
            session_id: Optional session ID for multi-turn dialogue
            enable_multi_turn: Override config setting for multi-turn mode
            prompt_builder: Optional callable to build a custom LLM prompt using
                (question, prepared_context, query_info, dialogue_history)

        Returns:
            Dictionary with answer and metadata (including summary if multi-turn)
        """
        if not self.repo_indexed:
            raise RuntimeError("Repository not indexed. Call index_repository() first.")

        # Determine if multi-turn mode is enabled
        if enable_multi_turn is None:
            enable_multi_turn = self.config.get("generation", {}).get("enable_multi_turn", False)

        if repo_filter:
            self.logger.info(f"Processing query: {question} in repositories: {repo_filter}")
        else:
            self.logger.info(f"Processing query: {question}")

        # Get dialogue history if in multi-turn mode
        dialogue_history = []
        if enable_multi_turn and session_id:
            # Get recent summaries from cache (last 10 turns for iterative agent)
            history_summary_rounds = self.config.get("query", {}).get("history_summary_rounds", 10)
            dialogue_history = self.cache_manager.get_recent_summaries(session_id, history_summary_rounds)

            if dialogue_history:
                self.logger.info(f"Retrieved {len(dialogue_history)} previous dialogue summaries")

        # NOTE: Query result caching is disabled to ensure full iterative_agent flow
        # Original cache logic (disabled):
        # use_cache = (not enable_multi_turn or not session_id) and self._should_use_cache()
        # cached_result = None
        # cache_key = None
        # repo_hash = None
        # if use_cache:
        #     repo_hash = self._get_repo_hash()
        #     cache_key = f"{question}_{','.join(sorted(repo_filter)) if repo_filter else 'all'}"
        #     cached_result = self.cache_manager.get_query_result(cache_key, repo_hash)
        #     if cached_result:
        #         self.logger.info("Returning cached result")
        # result = cached_result

        result = None  # Always process through full flow
        processed_query = None
        retrieved: List[CodeElement] = []

        try:
            if result is None:
                # Determine if iterative enhancement should be used
                use_iterative_enhancement = (
                    self.retriever.enable_agency_mode
                    and self.retriever.iterative_agent is not None
                )

                # Process query: skip query_processor entirely in iterative mode
                if use_iterative_enhancement:
                    # Iterative agent will handle all query enhancement
                    # Create minimal ProcessedQuery object
                    from .query_processor import ProcessedQuery
                    processed_query = ProcessedQuery(
                        original=question,
                        expanded=question,
                        keywords=[],
                        intent="unknown",
                        subqueries=[],
                        filters=filters or {},
                        rewritten_query=None,
                        pseudocode_hints=None,
                        search_strategy=None
                    )
                    self.logger.info("Iterative mode: skipping query_processor, all enhancements handled by iterative_agent")
                else:
                    # Standard mode: use full query processing
                    processed_query = self.query_processor.process(
                        question,
                        dialogue_history,
                        use_llm_enhancement=True
                    )
                    self.logger.info(f"Query intent: {processed_query.intent}")
                    self.logger.info(f"Keywords: {processed_query.keywords}")

                # Retrieve relevant code (with repository filter and agency mode)
                # Pass ProcessedQuery object for enhanced retrieval
                # Pass dialogue_history for multi-turn context in iterative mode
                retrieved = self.retriever.retrieve(
                    processed_query,  # Pass full ProcessedQuery object for multi-repo support
                    filters=filters,
                    repo_filter=repo_filter,
                    use_agency_mode=use_agency_mode,
                    dialogue_history=dialogue_history if enable_multi_turn else None
                )

                # Generate answer (with dialogue history for multi-turn)
                result = self.answer_generator.generate(
                    question,
                    retrieved,
                    query_info=processed_query.to_dict(),
                    dialogue_history=self._get_full_dialogue_history(session_id, enable_multi_turn),
                    prompt_builder=prompt_builder
                )

            # Add repository information to result
            if repo_filter:
                result["searched_repositories"] = repo_filter

            # Persist dialogue for any session (even single-turn) so users keep history
            if session_id:
                turn_number = self._get_next_turn_number(session_id)
                summary = result.get("summary", "")
                # Use formatted sources from result instead of raw retrieved elements
                # This ensures proper display format when loading history
                sources = result.get("sources", [])
                # Ensure sources are fully JSON-serializable
                serializable_sources = self._ensure_jsonable_sources(sources)

                # Ensure metadata is JSON-serializable
                metadata = {
                    "intent": getattr(processed_query, "intent", None),
                    "keywords": getattr(processed_query, "keywords", None),
                    "repo_filter": repo_filter,
                    "multi_turn": enable_multi_turn,
                }
                serializable_metadata = self._ensure_jsonable_metadata(metadata)

                self.cache_manager.save_dialogue_turn(
                    session_id=session_id,
                    turn_number=turn_number,
                    query=question,
                    answer=result.get("answer", ""),
                    summary=summary,
                    retrieved_elements=serializable_sources,
                    metadata=serializable_metadata
                )

                self.logger.info(f"Saved dialogue turn {turn_number} for session {session_id}")

            # Cache result for stateless flows (including single-turn sessions)
            # NOTE: Query result caching is disabled to ensure full iterative_agent flow
            # if use_cache and result is not None and cache_key and repo_hash:
            #     self.cache_manager.set_query_result(cache_key, repo_hash, result)

            return result

        except Exception as e:
            self.logger.error(f"Query failed: {e}")
            return {
                "answer": f"Error processing query: {str(e)}",
                "query": question,
                "error": str(e),
            }"},{"source_id":"9e3d9b4b251579d6bb3f8804f02ae87d7b2accd626fd4ead2d79d0143642d6f9","alias_source_ids":["9e3d9b4b251579d6bb3f8804f02ae87d7b2accd626fd4ead2d79d0143642d6f9"],"path":"fastcode/main.py","symbol":"FastCode.get_repository_summary","text":"def get_repository_summary(self) -> str:
        """Get summary of the loaded repository"""
        if not self.repo_info:
            return "No repository loaded"

        summary_parts = [
            f"Repository: {self.repo_info.get('name', 'Unknown')}",
            f"Files: {self.repo_info.get('file_count', 0)}",
            f"Size: {self.repo_info.get('total_size_mb', 0):.2f} MB",
        ]

        if self.repo_indexed:
            summary_parts.append(f"Indexed elements: {self.vector_store.get_count()}")

        return "\n".join(summary_parts)"},{"source_id":"6972ec4abc6709ea1067d6ff51c527e247e67ef0eafa1bb3fb9f676f585197cb","alias_source_ids":["6972ec4abc6709ea1067d6ff51c527e247e67ef0eafa1bb3fb9f676f585197cb"],"path":"fastcode/module_resolver.py","symbol":"ModuleResolver.__init__","text":"def __init__(self, index: GlobalIndexBuilder):
        """
        Initialize resolver with dependency injection.

        Args:
            index: GlobalIndexBuilder instance containing module_map and other lookup tables
        """
        self.index = index"},{"source_id":"16f555bbef39f866b83fd033ea08bacc47b239785b29f138c159da80d03911a0","alias_source_ids":["16f555bbef39f866b83fd033ea08bacc47b239785b29f138c159da80d03911a0"],"path":"fastcode/parser.py","symbol":"CodeParser._fix_common_syntax_errors","text":"def _fix_common_syntax_errors(self, content: str) -> str:
        """
        Fix common syntax errors in generated code.

        Some generated files may have syntax errors like:
        - except Exception as exc as exc: (duplicate 'as' clause)

        Args:
            content: File content that may contain syntax errors

        Returns:
            Content with common syntax errors fixed
        """
        import re

        # Fix duplicate 'as' clause in except statements
        # Pattern: except SomeException as var as var:
        content = re.sub(
            r'except\s+(\w+)\s+as\s+(\w+)\s+as\s+\2\s*:',
            r'except \1 as \2:',
            content
        )

        return content"},{"source_id":"0f334d8bfb5143c931de53abbbd397724b70f1e06fbe22cc7356345bd765261b","alias_source_ids":["0f334d8bfb5143c931de53abbbd397724b70f1e06fbe22cc7356345bd765261b"],"path":"fastcode/parser.py","symbol":"CodeParser._extract_c_classes_and_functions.visit_node","text":"def visit_node(node, current_class=None):
            # C++ classes or C structs
            if node.type in ('class_specifier', 'struct_specifier'):
                class_info = self._extract_c_class(node, content, code_bytes, language)
                if class_info:
                    classes.append(class_info)
            # Functions
            elif node.type == 'function_definition':
                func_info = self._extract_c_function(node, content, code_bytes, current_class)
                if func_info:
                    functions.append(func_info)
            else:
                # Recursively visit children
                for child in node.children:
                    if node.type in ('class_specifier', 'struct_specifier'):
                        visit_node(child, node)
                    else:
                        visit_node(child, current_class)"},{"source_id":"5d067f8ea8dd4134cf821f2ecf68c4e5d97818ae9430c435ca1f0f8ef32aba05","alias_source_ids":["5d067f8ea8dd4134cf821f2ecf68c4e5d97818ae9430c435ca1f0f8ef32aba05"],"path":"fastcode/query_processor.py","symbol":"QueryProcessor._detect_intent","text":"def _detect_intent(self, query: str) -> str:
        """Detect query intent"""
        query_lower = query.lower()

        # Check for each intent
        intent_scores = {}
        for intent, patterns in self.intent_patterns.items():
            score = sum(1 for pattern in patterns if pattern in query_lower)
            intent_scores[intent] = score

        # Get intent with highest score
        if intent_scores:
            max_score = max(intent_scores.values())
            if max_score > 0:
                for intent, score in intent_scores.items():
                    if score == max_score:
                        self.logger.debug(f"Detected intent: {intent}")
                        return intent

        return "general""},{"source_id":"7118ea5fdc502a3e9c920aad55cc309842d939d3a930872c26b2d1a3e0e02869","alias_source_ids":["7118ea5fdc502a3e9c920aad55cc309842d939d3a930872c26b2d1a3e0e02869"],"path":"fastcode/query_processor.py","symbol":"QueryProcessor._extract_keywords","text":"def _extract_keywords(self, query: str) -> List[str]:
        """Extract important keywords from query"""
        # Remove common words
        stopwords = {
            "the", "a", "an", "and", "or", "but", "in", "on", "at", "to", "for",
            "of", "with", "by", "from", "as", "is", "was", "are", "were", "be",
            "been", "being", "have", "has", "had", "do", "does", "did", "will",
            "would", "could", "should", "may", "might", "can", "this", "that",
            "these", "those", "i", "you", "he", "she", "it", "we", "they",
        }

        # Tokenize and filter
        words = re.findall(r'\b\w+\b', query.lower())
        keywords = [w for w in words if w not in stopwords and len(w) > 2]

        # Prioritize code-related keywords
        prioritized = [k for k in keywords if k in self.code_keywords]
        other = [k for k in keywords if k not in self.code_keywords]

        return prioritized + other"},{"source_id":"eee155767b7288f966c35edd3473ae0612e6882e548c6a936a5e45c093040ff7","alias_source_ids":["eee155767b7288f966c35edd3473ae0612e6882e548c6a936a5e45c093040ff7"],"path":"fastcode/query_processor.py","symbol":"QueryProcessor._expand_query","text":"def _expand_query(self, query: str) -> str:
        """Expand query with synonyms and related terms"""
        # Simple expansion with common synonyms
        expansions = {
            "function": ["function", "method", "procedure", "routine"],
            "method": ["method", "function", "member function"],
            "class": ["class", "object", "type"],
            "error": ["error", "exception", "bug", "issue"],
            "api": ["api", "endpoint", "route", "service"],
            "database": ["database", "db", "storage", "persistence"],
            "auth": ["authentication", "authorization", "auth", "login"],
            "test": ["test", "unittest", "spec", "testing"],
        }

        expanded_terms = []
        words = query.lower().split()

        for word in words:
            if word in expansions:
                # Add original and expansions
                expanded_terms.extend(expansions[word])
            else:
                expanded_terms.append(word)

        # Remove duplicates while preserving order
        seen = set()
        unique_terms = []
        for term in expanded_terms:
            if term not in seen:
                seen.add(term)
                unique_terms.append(term)

        expanded = " ".join(unique_terms)

        if expanded != query.lower():
            self.logger.debug(f"Expanded query: {expanded}")

        return expanded"},{"source_id":"93fb14799791b66e06e15a410298f0cd03d16a95fd47070c96af68e60097b874","alias_source_ids":["93fb14799791b66e06e15a410298f0cd03d16a95fd47070c96af68e60097b874"],"path":"fastcode/query_processor.py","symbol":"QueryProcessor._decompose_query","text":"def _decompose_query(self, query: str) -> List[str]:
        """Decompose complex queries into sub-queries"""
        # Check if query is complex (contains multiple clauses)
        if len(query.split()) < 10:
            return []  # Too short to decompose

        subqueries = []

        # Split by common separators
        separators = [" and ", " or ", ", ", "; "]
        parts = [query]

        for sep in separators:
            new_parts = []
            for part in parts:
                new_parts.extend(part.split(sep))
            parts = new_parts

        # Filter and clean subqueries
        for part in parts:
            part = part.strip()
            if len(part) > 15 and part != query:  # Must be substantial
                subqueries.append(part)

        # Limit number of subqueries
        subqueries = subqueries[:self.max_subqueries]

        if subqueries:
            self.logger.debug(f"Decomposed into {len(subqueries)} sub-queries")

        return subqueries"},{"source_id":"ca4daef522b79e589edd11c99dd414af6079823d4e5a6965fb7cd5c67c120784","alias_source_ids":["ca4daef522b79e589edd11c99dd414af6079823d4e5a6965fb7cd5c67c120784"],"path":"fastcode/query_processor.py","symbol":"QueryProcessor.is_code_query","text":"def is_code_query(self, query: str) -> bool:
        """Check if query is asking about code"""
        query_lower = query.lower()

        # Check for code-related keywords
        code_indicators = [
            "function", "class", "method", "variable", "code",
            "implementation", "how to", "algorithm", "logic",
            "file", "module", "import", "api", "endpoint",
        ]

        return any(indicator in query_lower for indicator in code_indicators)"},{"source_id":"bd516e4a52e5f64ec0a57453fa392da4822a363b758b29be2d7748481a309fa7","alias_source_ids":["bd516e4a52e5f64ec0a57453fa392da4822a363b758b29be2d7748481a309fa7"],"path":"fastcode/query_processor.py","symbol":"QueryProcessor.extract_code_entity","text":"def extract_code_entity(self, query: str) -> Optional[Tuple[str, str]]:
        """
        Extract code entity mention from query

        Returns:
            Tuple of (entity_type, entity_name) or None
        """
        # Pattern: "function named X", "class X", "X function", etc.
        patterns = [
            (r'function\s+(?:named\s+)?[\"\']?(\w+)[\"\']?', 'function'),
            (r'class\s+(?:named\s+)?[\"\']?(\w+)[\"\']?', 'class'),
            (r'method\s+(?:named\s+)?[\"\']?(\w+)[\"\']?', 'function'),
            (r'[\"\'](\w+)[\"\']?\s+function', 'function'),
            (r'[\"\'](\w+)[\"\']?\s+class', 'class'),
        ]

        query_lower = query.lower()

        for pattern, entity_type in patterns:
            match = re.search(pattern, query_lower)
            if match:
                entity_name = match.group(1)
                return (entity_type, entity_name)

        return None"},{"source_id":"f2622f98a09110fdfebee5dbfd2a829116714e44a8ff2597765ee849511d6c64","alias_source_ids":["f2622f98a09110fdfebee5dbfd2a829116714e44a8ff2597765ee849511d6c64"],"path":"fastcode/query_processor.py","symbol":"QueryProcessor._enhance_with_llm","text":"def _enhance_with_llm(self, query: str, intent: str, 
                         keywords: List[str], filters: Dict[str, Any]) -> Dict[str, Any]:
        """
        Use LLM to enhance query understanding and expansion

        Args:
            query: Original user query
            intent: Detected intent
            keywords: Extracted keywords
            filters: Extracted filters

        Returns:
            Dictionary with enhancement information
        """
        prompt = self._build_enhancement_prompt(query, intent, keywords, filters)

        try:
            if self.provider == "openai":
                response = self._call_openai(prompt)
            elif self.provider == "anthropic":
                response = self._call_anthropic(prompt)
            else:
                return {}

            print(f"LLM response of _enhance_with_llm: {response}")

            # Parse LLM response
            enhancements = self._parse_llm_response(response, intent)
            return enhancements

        except Exception as e:
            self.logger.error(f"LLM enhancement error: {e}")
            return {}"},{"source_id":"2b887cdfbb6b0670ba54f46c72fc0805c4ac93912c4810fc617e81d80314c62a","alias_source_ids":["2b887cdfbb6b0670ba54f46c72fc0805c4ac93912c4810fc617e81d80314c62a"],"path":"fastcode/query_processor.py","symbol":"QueryProcessor._parse_llm_response.clean_markdown","text":"def clean_markdown(text: str) -> str:
            """Remove markdown formatting from text"""
            # Remove bold markers
            text = re.sub(r'\*\*([^*]+)\*\*', r'\1', text)
            # Remove italic markers
            text = re.sub(r'\*([^*]+)\*', r'\1', text)
            # Remove inline code backticks (single backticks)
            text = re.sub(r'`([^`]+)`', r'\1', text)
            # Remove any remaining backticks
            text = text.replace('`', '')
            # Remove leading/trailing asterisks
            text = text.strip('*').strip()
            return text"},{"source_id":"92bd6c256596df8ae9c5db1e3d50a7b7e605844b3d6aef217556a51d38c32a55","alias_source_ids":["92bd6c256596df8ae9c5db1e3d50a7b7e605844b3d6aef217556a51d38c32a55"],"path":"fastcode/query_processor.py","symbol":"QueryProcessor._parse_rewritten_query","text":"def _parse_rewritten_query(self, response: str) -> Optional[str]:
        """Parse LLM response to extract rewritten query"""
        # Clean up the response
        rewritten = response.strip()

        # Remove common prefixes if present
        prefixes_to_remove = [
            "rewritten query:",
            "rewritten:",
            "query:",
        ]

        for prefix in prefixes_to_remove:
            if rewritten.lower().startswith(prefix):
                rewritten = rewritten[len(prefix):].strip()

        # Remove quotes if present
        if rewritten.startswith('"') and rewritten.endswith('"'):
            rewritten = rewritten[1:-1]
        elif rewritten.startswith("'") and rewritten.endswith("'"):
            rewritten = rewritten[1:-1]

        return rewritten if rewritten else None"},{"source_id":"9968b8f0108b931fe2521da009792dd2cacf9068047eb5f4f7b228e31d2391e4","alias_source_ids":["9968b8f0108b931fe2521da009792dd2cacf9068047eb5f4f7b228e31d2391e4"],"path":"fastcode/repo_overview.py","symbol":"RepositoryOverviewGenerator.parse_file_structure","text":"def parse_file_structure(self, repo_path: str, files: List[Dict[str, Any]]) -> Dict[str, Any]:
        """
        Parse repository file structure from scanned files

        Args:
            repo_path: Path to repository
            files: List of file metadata from loader

        Returns:
            Structured representation of repository
        """
        structure = {
            "total_files": len(files),
            "languages": {},
            "directories": {},
            "file_types": {},
            "all_files": [],
            "key_files": [],
        }

        for file_info in files:
            rel_path = file_info["relative_path"]
            extension = file_info["extension"]
            structure["all_files"].append(rel_path)

            # Count by extension
            if extension not in structure["file_types"]:
                structure["file_types"][extension] = 0
            structure["file_types"][extension] += 1

            # Count by language (simple heuristic)
            language = self._get_language_from_extension(extension)
            if language != "unknown":
                if language not in structure["languages"]:
                    structure["languages"][language] = 0
                structure["languages"][language] += 1

            # Build directory tree
            dir_name = os.path.dirname(rel_path)
            if dir_name:
                dir_parts = dir_name.split(os.sep)
                for i in range(len(dir_parts)):
                    partial_dir = os.sep.join(dir_parts[:i+1])
                    if partial_dir not in structure["directories"]:
                        structure["directories"][partial_dir] = []

                    file_name = os.path.basename(rel_path)
                    if i == len(dir_parts) - 1:  # This is the file's direct parent
                        if file_name not in structure["directories"][partial_dir]:
                            structure["directories"][partial_dir].append(file_name)
            # else:
            #     root_key = repo_path 

            #     if root_key not in structure["directories"]:
            #         structure["directories"][root_key] = []

            #     file_name = os.path.basename(rel_path)
            #     if file_name not in structure["directories"][root_key]:
            #         structure["directories"][root_key].append(file_name)

            # Identify key files
            if self._is_key_file(rel_path):
                structure["key_files"].append(rel_path)

        return structure"},{"source_id":"1055897884939446d5bacca85dc39597738794214a44b8dcae9b953ada6cff3f","alias_source_ids":["1055897884939446d5bacca85dc39597738794214a44b8dcae9b953ada6cff3f"],"path":"fastcode/repo_overview.py","symbol":"RepositoryOverviewGenerator._generate_structure_based_overview","text":"def _generate_structure_based_overview(self, repo_name: str,
                                          file_structure: Dict[str, Any]) -> str:
        """Generate overview based on file structure when README is unavailable"""

        languages = file_structure.get("languages", {})
        total_files = file_structure.get("total_files", 0)
        key_files = file_structure.get("key_files", [])

        # Determine primary language
        if languages:
            primary_lang = max(languages.items(), key=lambda x: x[1])[0]
        else:
            primary_lang = "unknown"

        # Infer project type from key files
        project_type = self._infer_project_type(key_files, languages)

        summary = f"{repo_name} is a {primary_lang} {project_type} with {total_files} files. "

        if len(languages) > 1:
            lang_list = ", ".join(languages.keys())
            summary += f"It uses multiple languages: {lang_list}. "

        if key_files:
            summary += f"Key entry points include: {', '.join(key_files[:5])}."

        return summary"},{"source_id":"85c3c88970bf0bcea0433b27bc32fcd89d625b4dc734ec1e5b91d8ef278aa22e","alias_source_ids":["85c3c88970bf0bcea0433b27bc32fcd89d625b4dc734ec1e5b91d8ef278aa22e"],"path":"fastcode/repo_selector.py","symbol":"RepositorySelector.enhance_query_with_file_hints","text":"def enhance_query_with_file_hints(self, query: str,
                                     selected_files: List[Dict[str, str]]) -> str:
        """
        Enhance query with file hints for better retrieval

        Args:
            query: Original query
            selected_files: Selected files from LLM

        Returns:
            Enhanced query string
        """
        if not selected_files:
            return query

        # Add file paths as context to query
        file_hints = []
        for sf in selected_files[:5]:  # Limit to top 5
            file_hints.append(f"{sf['repo_name']}/{sf['file_path']}")

        enhanced = f"{query} [Relevant files: {', '.join(file_hints)}]"
        return enhanced"},{"source_id":"5552e18e7072ff0bceb6710447ff4cf7a16db0d9ddbe1be9c8470165355a6081","alias_source_ids":["5552e18e7072ff0bceb6710447ff4cf7a16db0d9ddbe1be9c8470165355a6081"],"path":"fastcode/retriever.py","symbol":"HybridRetriever.index_for_bm25","text":"def index_for_bm25(self, elements: List[CodeElement]):
        """
        Build full BM25 index for keyword search (excludes repository overviews)

        Args:
            elements: List of code elements (without repository_overview type)
        """
        self.logger.info("Building full BM25 index for keyword search")

        self.full_bm25_elements = elements
        self.full_bm25_corpus = []

        for elem in elements:
            # Skip repository_overview elements if any (they should be in separate storage)
            if elem.type == "repository_overview":
                continue

            # Combine different text fields for indexing
            text_parts = [
                elem.name,
                elem.type,
                elem.language,
                elem.relative_path,
            ]

            if elem.docstring:
                text_parts.append(elem.docstring)

            if elem.signature:
                text_parts.append(elem.signature)

            if elem.summary:
                text_parts.append(elem.summary)

            # Add some code content
            if elem.code:
                text_parts.append(elem.code[:1000])  # First 1000 chars

            text = " ".join(text_parts)
            # Tokenize (simple whitespace tokenization)
            tokens = text.lower().split()
            self.full_bm25_corpus.append(tokens)

        self.full_bm25 = BM25Okapi(self.full_bm25_corpus)
        self.logger.info(f"Built full BM25 index with {len(self.full_bm25_corpus)} documents")"},{"source_id":"c4c8a1aae4e8162a15519af3e047c6c6950e9881997bcb98432ee4e2f3aeaa66","alias_source_ids":["c4c8a1aae4e8162a15519af3e047c6c6950e9881997bcb98432ee4e2f3aeaa66"],"path":"fastcode/retriever.py","symbol":"HybridRetriever._semantic_search","text":"def _semantic_search(self, query: str, top_k: int = 20, 
                         repo_filter: Optional[List[str]] = None) -> List[Tuple[Dict[str, Any], float]]:
        """
        Semantic search using embeddings
        Uses filtered_vector_store if available, otherwise uses full vector_store
        """
        # Embed query
        query_embedding = self.embedder.embed_text(query)

        # Choose which vector store to use
        if self.filtered_vector_store is not None and self.filtered_vector_store.get_count() > 0:
            # Use filtered vector store
            # IMPORTANT: Still pass repo_filter for double-checking, in case filtered store has stale data
            results = self.filtered_vector_store.search(
                query_embedding,
                k=top_k * 2,  # Get more candidates for filtering
                min_score=self.min_similarity,
                repo_filter=repo_filter  # Apply filter for safety
            )
            self.logger.debug(f"Semantic search (filtered) found {len(results)} results")
        else:
            # Use full vector store with repo_filter
            results = self.vector_store.search(
                query_embedding,
                k=top_k,
                min_score=self.min_similarity,
                repo_filter=repo_filter
            )
            self.logger.debug(f"Semantic search (full) found {len(results)} results")

        # Additional safety check: manually filter results by repo
        if repo_filter:
            filtered_results = []
            for metadata, score in results:
                repo_name = metadata.get("repo_name", "")
                if repo_name in repo_filter:
                    filtered_results.append((metadata, score))
                else:
                    self.logger.warning(
                        f"Semantic search returned element from unexpected repo: {repo_name} "
                        f"(expected: {repo_filter}). Element: {metadata.get('name', 'unknown')}"
                    )
            results = filtered_results[:top_k]  # Limit to top_k after filtering

        return results"},{"source_id":"672152dafeb9e775564a40281db44bc4b0ea756b8b9d5239667b43dd4dffc65b","alias_source_ids":["672152dafeb9e775564a40281db44bc4b0ea756b8b9d5239667b43dd4dffc65b"],"path":"fastcode/retriever.py","symbol":"HybridRetriever._rerank","text":"def _rerank(self, query: str, results: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
        """Re-rank results based on additional factors"""
        # Simple re-ranking based on element type preferences
        type_weights = {
            "function": 1.2,  # Prefer functions
            "class": 1.1,     # Then classes
            "file": 0.9,      # Then files
            "documentation": 0.8,  # Then docs
        }

        for result in results:
            elem_type = result["element"].get("type", "")
            weight = type_weights.get(elem_type, 1.0)
            # Apply weight to all score components to maintain consistency
            result["total_score"] *= weight
            result["semantic_score"] *= weight
            result["keyword_score"] *= weight
            result["pseudocode_score"] *= weight
            result["graph_score"] *= weight

        # Sort by updated scores
        results.sort(key=lambda x: x["total_score"], reverse=True)

        return results"},{"source_id":"42e32ad5d9ffdb60e15ef62b7fcc5804da659c2f14129552fead458bfdec396e","alias_source_ids":["42e32ad5d9ffdb60e15ef62b7fcc5804da659c2f14129552fead458bfdec396e"],"path":"fastcode/retriever.py","symbol":"HybridRetriever._apply_filters","text":"def _apply_filters(self, results: List[Dict[str, Any]], 
                       filters: Dict[str, Any]) -> List[Dict[str, Any]]:
        """Apply filters to results"""
        filtered = []

        for result in results:
            elem = result["element"]

            # Check language filter
            if "language" in filters:
                if elem.get("language") != filters["language"]:
                    continue

            # Check type filter
            if "type" in filters:
                if elem.get("type") != filters["type"]:
                    continue

            # Check file path filter
            if "file_path" in filters:
                if filters["file_path"] not in elem.get("relative_path", ""):
                    continue

            filtered.append(result)

        return filtered"},{"source_id":"ff351f4dfda0da31e1e6f6f083b5adb3680d261d105c6e41f7abf63a8caa8648","alias_source_ids":["ff351f4dfda0da31e1e6f6f083b5adb3680d261d105c6e41f7abf63a8caa8648"],"path":"fastcode/retriever.py","symbol":"HybridRetriever._final_repo_filter","text":"def _final_repo_filter(self, results: List[Dict[str, Any]], repo_filter: List[str]) -> List[Dict[str, Any]]:
        """
        Final safety filter to ensure only results from selected repositories are returned
        This is a critical safety check to prevent leakage of results from other repositories

        Args:
            results: List of retrieval results
            repo_filter: List of allowed repository names

        Returns:
            Filtered results containing only elements from allowed repositories
        """
        if not repo_filter:
            return results

        filtered_results = []
        filtered_count = 0

        for result in results:
            elem = result["element"]
            repo_name = elem.get("repo_name", "")

            if repo_name in repo_filter:
                filtered_results.append(result)
            else:
                filtered_count += 1
                self.logger.warning(
                    f"Filtered out element from unexpected repo: {repo_name} "
                    f"(expected one of: {repo_filter}). Element: {elem.get('name', 'unknown')}"
                )

        if filtered_count > 0:
            self.logger.warning(
                f"Final repo filter removed {filtered_count} elements from unexpected repositories. "
                f"This indicates a potential issue in the retrieval pipeline."
            )

        return filtered_results"},{"source_id":"f0442236543dc88d18fca02b406037b407f09c1cdb02363ecc01664888f33d8f","alias_source_ids":["f0442236543dc88d18fca02b406037b407f09c1cdb02363ecc01664888f33d8f"],"path":"fastcode/retriever.py","symbol":"HybridRetriever.retrieve_by_file","text":"def retrieve_by_file(self, file_path: str) -> List[Dict[str, Any]]:
        """Retrieve all elements from a specific file"""
        results = []

        # Use filtered elements if available, otherwise use full elements
        elements_to_search = (self.filtered_bm25_elements 
                             if self.filtered_bm25_elements 
                             else self.full_bm25_elements)

        for elem in elements_to_search:
            if elem.file_path == file_path or elem.relative_path == file_path:
                results.append({
                    "element": elem.to_dict(),
                    "semantic_score": 0.0,
                    "keyword_score": 0.0,
                    "graph_score": 0.0,
                    "total_score": 1.0,
                })

        return results"},{"source_id":"2a6b1d5e31cbaca965ffb0ed0009e8ba4bcb9d9091b0a2d7ce5912644e474bd9","alias_source_ids":["2a6b1d5e31cbaca965ffb0ed0009e8ba4bcb9d9091b0a2d7ce5912644e474bd9"],"path":"fastcode/retriever.py","symbol":"HybridRetriever.save_bm25","text":"def save_bm25(self, name: str = "index"):
        """
        Save FULL BM25 index and elements to disk

        Args:
            name: Name for the saved files
        """
        bm25_path = os.path.join(self.persist_dir, f"{name}_bm25.pkl")

        try:
            with open(bm25_path, 'wb') as f:
                pickle.dump({
                    "bm25_corpus": self.full_bm25_corpus,
                    "bm25_elements": [elem.to_dict() for elem in self.full_bm25_elements],
                }, f)

            self.logger.info(f"Saved full BM25 data to {bm25_path}")
            return True

        except Exception as e:
            self.logger.error(f"Failed to save BM25 data: {e}")
            return False"},{"source_id":"4decc2a0e8c44e82edc968fa7174d9b55c483338ae066fb588e6a5985dfbc0d5","alias_source_ids":["4decc2a0e8c44e82edc968fa7174d9b55c483338ae066fb588e6a5985dfbc0d5"],"path":"fastcode/retriever.py","symbol":"HybridRetriever.load_bm25","text":"def load_bm25(self, name: str = "index") -> bool:
        """
        Load FULL BM25 index and elements from disk

        Args:
            name: Name of the saved files

        Returns:
            True if successful, False otherwise
        """
        bm25_path = os.path.join(self.persist_dir, f"{name}_bm25.pkl")

        if not os.path.exists(bm25_path):
            self.logger.warning(f"BM25 data not found: {bm25_path}")
            return False

        try:
            with open(bm25_path, 'rb') as f:
                data = pickle.load(f)
                self.full_bm25_corpus = data["bm25_corpus"]

                # Reconstruct CodeElement objects
                self.full_bm25_elements = []
                for elem_dict in data["bm25_elements"]:
                    self.full_bm25_elements.append(CodeElement(**elem_dict))

            # Rebuild FULL BM25 index from corpus
            if self.full_bm25_corpus:
                self.full_bm25 = BM25Okapi(self.full_bm25_corpus)
                self.logger.info(f"Loaded full BM25 data with {len(self.full_bm25_elements)} elements")
            else:
                self.logger.warning("BM25 corpus is empty")

            return True

        except Exception as e:
            self.logger.error(f"Failed to load BM25 data: {e}")
            return False"},{"source_id":"1fa63658f729af88bd54c674e819f9858342db2be9e0dcd6b0821f4e0b28256c","alias_source_ids":["1fa63658f729af88bd54c674e819f9858342db2be9e0dcd6b0821f4e0b28256c"],"path":"fastcode/retriever.py","symbol":"HybridRetriever.set_repo_root","text":"def set_repo_root(self, repo_root: str):
        """
        Set repository root and initialize agents if agency mode is enabled

        Args:
            repo_root: Root directory of the repository
        """
        self.repo_root = repo_root
        if self.enable_agency_mode and not self.iterative_agent:
            self._initialize_agents(repo_root)"},{"source_id":"e7510cca5235adc213f163d7d6130ce424c3c74615346a2a807d73fcddc3627c","alias_source_ids":["e7510cca5235adc213f163d7d6130ce424c3c74615346a2a807d73fcddc3627c"],"path":"fastcode/retriever.py","symbol":"HybridRetriever._apply_agency_mode","text":"def _apply_agency_mode(self, query: str, results: List[Dict[str, Any]],
                          query_info: Dict[str, Any],
                          repo_filter: Optional[List[str]] = None,
                          dialogue_history: Optional[List[Dict[str, Any]]] = None) -> List[Dict[str, Any]]:
        """
        Apply agency mode: iterative retrieval with confidence and cost control

        Args:
            query: User query
            results: Initial retrieval results (not used in iterative mode)
            query_info: Query information
            repo_filter: Optional list of repository names to filter by
            dialogue_history: Previous dialogue summaries for multi-turn context

        Returns:
            Enhanced results from iterative agency mode
        """
        self.logger.info("Applying iterative agency mode")

        try:
            # Use iterative agent if available
            if self.iterative_agent:
                # Get processed query (should be in query_info or we need to pass it)
                from .query_processor import ProcessedQuery

                # Create a ProcessedQuery object from query_info
                processed_query = ProcessedQuery(
                    original=query,
                    expanded=query_info.get("expanded", query),
                    keywords=query_info.get("keywords", []),
                    intent=query_info.get("intent", "unknown"),
                    subqueries=[],
                    filters=query_info.get("filters", {}),
                    rewritten_query=query_info.get("rewritten_query"),
                    pseudocode_hints=query_info.get("pseudocode_hints")
                )

                final_results, iteration_metadata = self.iterative_agent.retrieve_with_iteration(
                    query, processed_query, query_info, repo_filter, dialogue_history
                )

                self.logger.info(f"Iterative agent completed: {iteration_metadata}")

                return final_results

            # Fallback: iterative agent not available
            else:
                self.logger.warning("Iterative agent not available, returning original results")
                return results

        except Exception as e:
            self.logger.error(f"Error in agency mode: {e}")
            import traceback
            self.logger.error(traceback.format_exc())
            # Fallback to original results
            return results"},{"source_id":"3026cdcf72d7f2a3c0ccb1655cf7be6b3486b10867d7b6c0ec24e880c648df93","alias_source_ids":["3026cdcf72d7f2a3c0ccb1655cf7be6b3486b10867d7b6c0ec24e880c648df93"],"path":"fastcode/utils.py","symbol":"get_repo_name_from_url","text":"def get_repo_name_from_url(url: str) -> str:
    """Extract repository name from URL"""
    # Handle GitHub URLs
    if url.endswith(".git"):
        url = url[:-4]

    parts = url.rstrip("/").split("/")
    return parts[-1] if parts else "unknown_repo""},{"source_id":"d804bb83fdd19b5285d3dbe73a62a3f6b687ae7add7856a32e45b83549403e04","alias_source_ids":["d804bb83fdd19b5285d3dbe73a62a3f6b687ae7add7856a32e45b83549403e04"],"path":"fastcode/vector_store.py","symbol":"VectorStore.load_repo_overviews","text":"def load_repo_overviews(self) -> Dict[str, Dict[str, Any]]:
        """
        Load all repository overviews from storage

        Returns:
            Dictionary mapping repo_name to overview data
        """
        if self.in_memory:
            # Return the in-memory overviews when persistence is disabled.
            return self._in_memory_repo_overviews

        overview_path = os.path.join(self.persist_dir, "repo_overviews.pkl")

        if not os.path.exists(overview_path):
            self.logger.info("No repository overviews found")
            return {}

        try:
            with open(overview_path, 'rb') as f:
                overviews = pickle.load(f)
            self.logger.info(f"Loaded {len(overviews)} repository overviews")
            return overviews
        except Exception as e:
            self.logger.error(f"Failed to load repository overviews: {e}")
            return {}"},{"source_id":"8cdb1489da35b6e4fcd40072f6d138d3bcc8ede3164eac35bb4b98714774fe97","alias_source_ids":["8cdb1489da35b6e4fcd40072f6d138d3bcc8ede3164eac35bb4b98714774fe97"],"path":"fastcode/vector_store.py","symbol":"VectorStore.get_repository_names","text":"def get_repository_names(self) -> List[str]:
        """Get list of unique repository names in the store"""
        repo_names = set()
        for meta in self.metadata:
            repo_name = meta.get("repo_name")
            if repo_name:
                repo_names.add(repo_name)
        return sorted(list(repo_names))"},{"source_id":"8a2fb103ad7ee8998cf90f63e5ed4dea469de3b824ce8897154a9260e18b2be6","alias_source_ids":["8a2fb103ad7ee8998cf90f63e5ed4dea469de3b824ce8897154a9260e18b2be6"],"path":"fastcode/vector_store.py","symbol":"VectorStore.filter_by_repositories","text":"def filter_by_repositories(self, repo_names: List[str]) -> List[int]:
        """
        Get indices of vectors belonging to specific repositories

        Args:
            repo_names: List of repository names to filter by

        Returns:
            List of indices
        """
        indices = []
        for i, meta in enumerate(self.metadata):
            if meta.get("repo_name") in repo_names:
                indices.append(i)
        return indices"},{"source_id":"0d0864e396269bcb455b2662e28f479a30dc0df72b55b79a038c4703d11862ec","alias_source_ids":["0d0864e396269bcb455b2662e28f479a30dc0df72b55b79a038c4703d11862ec"],"path":"fastcode/vector_store.py","symbol":"VectorStore.save","text":"def save(self, name: str = "index"):
        """
        Save index and metadata to disk

        Args:
            name: Name for the saved files
        """
        if self.in_memory:
            self.logger.info("Skipping vector store save (in-memory mode enabled)")
            return

        if self.index is None:
            self.logger.warning("No index to save")
            return

        index_path = os.path.join(self.persist_dir, f"{name}.faiss")
        metadata_path = os.path.join(self.persist_dir, f"{name}_metadata.pkl")

        # Save FAISS index
        faiss.write_index(self.index, index_path)

        # Save metadata
        with open(metadata_path, 'wb') as f:
            pickle.dump({
                "metadata": self.metadata,
                "dimension": self.dimension,
                "distance_metric": self.distance_metric,
                "index_type": self.index_type,
            }, f)

        # Invalidate cache since we just modified the indexes
        self.invalidate_scan_cache()

        self.logger.info(f"Saved vector store to {self.persist_dir}")"},{"source_id":"056b235cbd1ebddfaf2f60a52837a2e8fd9d1bc1522dba77d3fef474a38ce625","alias_source_ids":["056b235cbd1ebddfaf2f60a52837a2e8fd9d1bc1522dba77d3fef474a38ce625"],"path":"mcp_server.py","symbol":"_repo_name_from_source","text":"def _repo_name_from_source(source: str, is_url: bool) -> str:
    """Derive a canonical repo name from a URL or local path."""
    from fastcode.utils import get_repo_name_from_url
    if is_url:
        return get_repo_name_from_url(source)
    # Local path: use the directory basename
    return os.path.basename(os.path.normpath(source))"},{"source_id":"ec940072e8ca2e7ae26e6b4d4b6f08d448095dc31cab91ba93a21f36f649ba64","alias_source_ids":["ec940072e8ca2e7ae26e6b4d4b6f08d448095dc31cab91ba93a21f36f649ba64"],"path":"mcp_server.py","symbol":"_is_repo_indexed","text":"def _is_repo_indexed(repo_name: str) -> bool:
    """Check whether a repo already has a persisted FAISS index."""
    fc = _get_fastcode()
    persist_dir = fc.vector_store.persist_dir
    faiss_path = os.path.join(persist_dir, f"{repo_name}.faiss")
    meta_path = os.path.join(persist_dir, f"{repo_name}_metadata.pkl")
    return os.path.exists(faiss_path) and os.path.exists(meta_path)"},{"source_id":"3bdeac89956f17801807b9abaeba7a998c39e5ab56d7a6549998c3e2c916f566","alias_source_ids":["3bdeac89956f17801807b9abaeba7a998c39e5ab56d7a6549998c3e2c916f566"],"path":"mcp_server.py","symbol":"code_qa","text":"@mcp.tool()
def code_qa(
    question: str,
    repos: list[str],
    multi_turn: bool = True,
    session_id: str | None = None,
) -> str:
    """Ask a question about one or more code repositories.

    This is the core tool for repo-level code understanding. FastCode will
    automatically clone (if URL) and index repositories that haven't been
    indexed yet, then answer your question using hybrid retrieval + LLM.

    Args:
        question: The question to ask about the code.
        repos: List of repository sources. Each can be:
               - A GitHub/GitLab URL (e.g. "https://github.com/user/repo")
               - A local filesystem path (e.g. "/home/user/projects/myrepo")
               If the repo is already indexed, it won't be re-indexed.
        multi_turn: Enable multi-turn conversation mode. When True, previous
                    Q&A context from the same session_id is used. Default: True.
        session_id: Session identifier for multi-turn conversations. If not
                    provided, a new session is created automatically. Pass the
                    same session_id across calls to continue a conversation.

    Returns:
        The answer to your question, with source references.
    """
    fc = _get_fastcode()

    # 1. Ensure all repos are indexed
    ready_names = _ensure_repos_ready(repos)
    if not ready_names:
        return "Error: None of the specified repositories could be loaded or indexed."

    # 2. Load indexed repos into memory (multi-repo merge)
    if not _ensure_loaded(fc, ready_names):
        return "Error: Failed to load repository indexes."

    # 3. Session management
    sid = session_id or str(uuid.uuid4())[:8]

    # 4. Query
    result = fc.query(
        question=question,
        # Always enforce repository filtering for both single-repo and
        # multi-repo queries to avoid cross-repo source leakage.
        repo_filter=ready_names,
        session_id=sid,
        enable_multi_turn=multi_turn,
    )

    answer = result.get("answer", "")
    sources = result.get("sources", [])

    # Format output
    parts = [answer]

    if sources:
        parts.append("\n\n---\nSources:")
        for s in sources[:]:
            file_path = s.get("file", s.get("relative_path", ""))
            repo = s.get("repo", s.get("repository", ""))
            name = s.get("name", "")
            start = s.get("start_line", "")
            end = s.get("end_line", "")
            if (not start or not end) and s.get("lines"):
                lines = str(s.get("lines", ""))
                if "-" in lines:
                    parsed_start, parsed_end = lines.split("-", 1)
                    start = start or parsed_start
                    end = end or parsed_end
            loc = f"L{start}-L{end}" if start and end else ""
            parts.append(f"  - {repo}/{file_path}:{loc} ({name})" if repo else f"  - {file_path}:{loc} ({name})")

    parts.append(f"\n[session_id: {sid}]")
    return "\n".join(parts)"},{"source_id":"1ce84645b09b84d5fbc31c3c0e0b73229e191f009b2ca724aa91bc37675d7cbd","alias_source_ids":["1ce84645b09b84d5fbc31c3c0e0b73229e191f009b2ca724aa91bc37675d7cbd"],"path":"mcp_server.py","symbol":"delete_session","text":"@mcp.tool()
def delete_session(session_id: str) -> str:
    """Delete a conversation session and all its history.

    Args:
        session_id: The session identifier to delete.

    Returns:
        Confirmation message.
    """
    fc = _get_fastcode()
